#[test]
fn window_build_matches_reference() {
    for index in 0..WINDOW_CASES {
        let (states, outputs, target, fallback_state, fallback_output) = window_input(index);
        let built = crate::build_features(states, outputs, target, fallback_state, fallback_output);
        let expected = window_expected(index);
        for t in 0..WINDOW {
            for ch in 0..FEATURES {
                assert!(
                    (built[t][ch] - expected[t][ch]).abs() < 1e-12,
                    "case {index} t={t} ch={ch}: built={} expected={}",
                    built[t][ch],
                    expected[t][ch]
                );
            }
        }
    }
}
